/** @var LcCrmPanel $this */
$h=[LcCrmPanel::class,'e']; $l=[LcCrmPanel::class,'label']; $assets=App()->assetManager->publish(__DIR__.'/assets');
$rowLink=fn($row)=>$this->link(['tab'=>'record','type'=>$row['type'],'id'=>$row['id']]);
$opt=static fn($a,$b)=>((string)$a===(string)$b?' selected':'');
$input=static fn($key,$value='',$type='text')=>'<input class="input" type="'.$h($type).'" name="'.$h($key).'" value="'.$h($value).'">';
$button=static fn($text)=>'<button class="btn" type="submit">'.$h($text).'</button>';
$post=fn($action)=>$this->csrf().CHtml::hiddenField('action',$action);
$team=$this->team; $type=$this->type; $role=$this->role;
?>
<!doctype html><html lang="pl" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>CRM · LimeControl</title><link rel="stylesheet" href="<?=$h($assets)?>/components.css"><link rel="stylesheet" href="<?=$h($assets)?>/panel.css"></head><body>
<header><strong>LimeControl CRM</strong><?php if($team): ?><span><?=$h($this->teams[$team])?> · <?=$h($l($role))?></span><?php endif; ?><a href="<?=$h(App()->createUrl('admin'))?>">Panel LimeSurvey</a></header><main>
<?php if($this->notice): ?><p class="notice" role="status"><?=$h($this->notice)?></p><?php endif; if($this->error): ?><p class="error" role="alert"><?=$h($this->error)?></p><?php endif; ?>
<?php if(count($this->teams)>1): ?><nav aria-label="Zespoły"><?php foreach($this->teams as $k=>$v): ?><a href="<?=$this->link(['team'=>$k])?>"><?=$h($v)?></a><?php endforeach; ?></nav><?php endif; ?>
<?php if(!$team || ($this->tab==='settings' && LimeControlCrm::admin())): ?><section class="sheet"><h1>Zespoły CRM</h1><?php if($this->groups): ?><form method="post" class="filters"><?=$post('enable')?><label>Grupa użytkowników LimeSurvey<select class="select" name="group"><?php foreach($this->groups as $g): ?><option value="<?=$h($g['ugid'])?>"><?=$h($g['name'])?></option><?php endforeach; ?></select></label><?=$button('Włącz CRM dla grupy')?></form><?php else: ?><p>Administrator może utworzyć grupę użytkowników w panelu LimeSurvey i włączyć dla niej CRM.</p><?php endif; ?></section><?php endif; ?>
<?php if($team): ?><nav class="actions" aria-label="CRM"><a class="btn" href="<?=$this->link(['tab'=>'board'])?>">Lejek</a><?php foreach(self::LABELS as $key=>$name): ?><a class="btn<?=$this->tab==='list' && $type===$key?' selected':''?>" href="<?=$this->link(['tab'=>'list','type'=>$key])?>"><?=$h($name)?></a><?php endforeach; if($role!=='worker'): ?><a class="btn" href="<?=$this->link(['tab'=>'reports'])?>">Raporty</a><a class="btn" href="<?=$this->link(['tab'=>'csv'])?>">CSV</a><?php endif; if($role==='admin'): ?><a class="btn" href="<?=$this->link(['tab'=>'settings'])?>">Ustawienia</a><?php endif; ?></nav>
<?php if($this->tab==='board'): $counts=$this->board('deal',$this->scope()); ?><h1>Lejek sprzedaży</h1><a class="btn" href="<?=$this->link(['tab'=>'edit','type'=>'deal'])?>">Dodaj zapytanie</a><div class="board"><?php foreach(LcCrmStore::STAGES as $stage): ?><section class="stage"><h2><a href="<?=$this->link(['tab'=>'list','type'=>'deal','filter'=>$stage])?>"><?=$h($l($stage))?></a> (<?=(int)($counts[$stage]??0)?>)</h2><ul><?php foreach($this->s->listing($team,'deal',$this->scope(),'',$stage,0,0,5) as $r): ?><li><a href="<?=$rowLink($r)?>"><?=$h($r['title'])?></a><small><?=$h(trim($r['amount'].' '.$r['currency'].' '.$r['due']))?></small></li><?php endforeach; ?></ul></section><?php endforeach; ?></div>
<?php elseif($this->tab==='list'): $search=$this->str('q'); $filter=$this->str('filter'); $mine=$this->str('mine')==='1'; $page=max(1,min(100000,(int)$this->str('page','1'))); $records=$this->s->listing($team,$type,$mine?$this->uid:$this->scope(),$search,$filter,0,($page-1)*50,51); ?>
<h1><?=$h(self::LABELS[$type])?></h1><a class="btn" href="<?=$this->link(['tab'=>'edit','type'=>$type])?>">Dodaj rekord</a><form method="get" action="<?=$h(strtok(App()->createUrl('plugins/direct'),'?'))?>" class="filters"><?php foreach(['r'=>'plugins/direct','plugin'=>'LimeControlCrm','function'=>'panel','tab'=>'list','team'=>$team,'type'=>$type] as $k=>$v) {echo CHtml::hiddenField($k,$v);} ?><label>Wyszukaj <?=$input('q',$search)?></label><label>Filtr<select class="select" name="filter"><option value="">Wszystkie</option><?php foreach(['today'=>'Na dziś','overdue'=>'Po terminie','unassigned'=>'Bez opiekuna']+array_combine(LcCrmStore::STATUSES[$type],array_map($l,LcCrmStore::STATUSES[$type])) as $k=>$v): ?><option value="<?=$h($k)?>"<?=$opt($filter,$k)?>><?=$h($v)?></option><?php endforeach; ?></select></label><label><span><input type="checkbox" name="mine" value="1"<?=$mine?' checked':''?>> Tylko moje</span></label><?=$button('Filtruj')?></form>
<div class="sheet overflow-x-auto"><table class="table"><thead><tr><th>Nazwa / temat</th><th>Opiekun</th><th>Etap / status</th><th>Termin</th></tr></thead><tbody><?php foreach(array_slice($records,0,50) as $r): ?><tr><td><a href="<?=$rowLink($r)?>"><?=$h($r['title'])?></a></td><td><?=$h($this->members[$r['owner_id']]??'Brak')?></td><td><?=$h($l($r['status']))?></td><td><?=$h($r['due'])?></td></tr><?php endforeach; ?></tbody></table><?php if(!$records): ?><p>Brak pasujących rekordów.</p><?php endif; ?></div><nav><?php foreach([$page-1=>'Poprzednia',$page+1=>'Następna'] as $n=>$caption): if($n>0 && ($n<$page || count($records)>50)): ?><a href="<?=$this->link(['tab'=>'list','type'=>$type,'q'=>$search,'filter'=>$filter,'mine'=>(int)$mine,'page'=>$n])?>"><?=$caption?></a><?php endif; endforeach; ?></nav>
<?php elseif($this->tab==='edit'): $r=$this->draft+$this->row; $links=match($type){'contact'=>['company'],'deal','case'=>['company','contact'],'task','note'=>['company','contact','deal','case'],default=>[]}; ?>
<h1><?=$this->id?'Edycja':'Nowy rekord'?> · <?=$h(self::LABELS[$type])?></h1><form class="sheet" method="post"><?=$post('save')?><?=CHtml::hiddenField('record[revision]',$this->row['revision']??0)?><div class="fields"><label>Nazwa / temat<input required maxlength="180" class="input" name="record[title]" value="<?=$h($r['title']??'')?>"></label><label>Etap / status<select class="select" name="record[status]"><?php foreach(LcCrmStore::STATUSES[$type] as $v): ?><option value="<?=$h($v)?>"<?=$opt($r['status']??'',$v)?>><?=$h($l($v))?></option><?php endforeach; ?></select></label>
<?php if($role!=='worker'): ?><label>Opiekun<select class="select" name="record[owner_id]"><option value="0">Brak</option><?php foreach($this->members as $k=>$v): ?><option value="<?=$h($k)?>"<?=$opt($r['owner_id']??0,$k)?>><?=$h($v)?></option><?php endforeach; ?></select></label><?php endif; if($links): $selected=$r['parent_id']??$this->str('parent'); ?><label>Powiązany rekord (ID)<input class="input" type="number" min="1" list="crm-parents" name="record[parent_id]" value="<?=$h($selected)?>"><datalist id="crm-parents"><?php foreach($links as $cat): foreach($this->s->listing($team,$cat,$this->scope(),'','',0,0,50) as $p): ?><option value="<?=$h($p['id'])?>"><?=$h($p['title'])?></option><?php endforeach; endforeach; ?></datalist></label><?php endif; ?>
<?php if(in_array($type,['deal','task','case'],true)): ?><label><?=$type==='deal'?'Termin decyzji':'Termin wykonania'?> <?=$input('record[due]',$r['due']??'','date')?></label><?php endif; foreach(LcCrmStore::FIELDS[$type] as $field): if(in_array($field,['participant_id','closed_at','order','sku','score','item_feedback','customer_ref'],true)){continue;} ?><label><?=$h($l($field))?><?php if($field==='priority'): ?><select class="select" name="record[priority]"><?php foreach(['low','normal','high','urgent'] as $v): ?><option value="<?=$h($v)?>"<?=$opt($r[$field]??'normal',$v)?>><?=$h($l($v))?></option><?php endforeach; ?></select><?php elseif(in_array($field,['body','resolution','next_action','loss_reason'],true)): ?><textarea class="textarea" name="record[<?=$h($field)?>]"><?=$h($r[$field]??'')?></textarea><?php else: echo $input('record['.$field.']',$r[$field]??($field==='currency'?'PLN':''),$field==='email'?'email':'text'); endif; ?></label><?php endforeach; ?></div><div class="actions"><?=$button('Zapisz')?></div></form>
<?php elseif($this->tab==='record' && $this->row): $r=$this->row; ?><h1><?=$h($r['title'])?></h1><div class="actions"><a class="btn" href="<?=$this->link(['type'=>$type,'tab'=>'edit','id'=>$r['id']])?>">Edytuj</a><?php if(in_array($type,['company','contact','deal','case'],true)): foreach(['note'=>'Dodaj notatkę lub rozmowę','task'=>'Dodaj zadanie'] as $k=>$v): ?><a class="btn" href="<?=$this->link(['type'=>$k,'tab'=>'edit','parent'=>$r['id']])?>"><?=$v?></a><?php endforeach; endif; foreach($this->detailLinks() as $link): ?><a class="btn" href="<?=$h($link['url'])?>"><?=$h($link['label'])?></a><?php endforeach; ?></div>
<dl class="sheet"><dt>ID</dt><dd><?=$h($r['id'])?></dd><dt>Opiekun</dt><dd><?=$h($this->members[$r['owner_id']]??'Brak')?></dd><?php if($r['parent_id'] && ($parent=$this->s->get($team,(int)$r['parent_id'])) && ($role!=='worker'||$parent['owner_id']===$this->uid)): ?><dt>Powiązany rekord</dt><dd><a href="<?=$rowLink($parent)?>"><?=$h($parent['title'])?></a></dd><?php endif; foreach(array_merge(['status','due'],LcCrmStore::FIELDS[$type]) as $field): if(($r[$field]??'')===''){continue;} ?><dt><?=$h($l($field))?></dt><dd><?=$h(in_array($field,['status','priority'],true)?$l($r[$field]):$r[$field])?></dd><?php endforeach; ?></dl>
<?php if($type==='contact' && $role==='admin'): ?><details class="sheet"><summary>Powiąż z uczestnikiem CPDB</summary><form method="post" class="filters"><?=$post('cpdb')?><?=CHtml::hiddenField('revision',$r['revision'])?><label>Numer zmapowanej ankiety <?=$input('survey','','number')?></label><label>ID uczestnika ankiety (TID) <?=$input('tid','','number')?></label><?=$button('Powiąż wskazanego uczestnika')?></form></details><?php endif; ?>
<section class="sheet"><h2>Historia zmian</h2><ul><?php foreach($this->s->history($team,$r['id']) as $e): ?><li><?=$h($e['happened'])?> UTC · <?=$h($this->members[$e['actor_id']]??($e['actor_id']?'#'.$e['actor_id']:'Integracja'))?> · <?=$h($e['description'])?></li><?php endforeach; ?></ul></section><?php foreach(['contact','deal','case','task','note'] as $cat): $items=$this->s->listing($team,$cat,$this->scope(),'','',$r['id'],0,50); if(!$items){continue;} ?><section class="sheet"><h2><?=$h(self::LABELS[$cat])?></h2><ul><?php foreach($items as $item): ?><li><a href="<?=$rowLink($item)?>"><?=$h($item['title'])?></a> · <?=$h($item['created'])?><?php if($cat==='note'): ?> · <?=$h($l($item['status']))?> · <?=$h($item['body'])?><?php endif; ?></li><?php endforeach; ?></ul></section><?php endforeach; ?>
<?php elseif($this->tab==='reports'): $from=$this->str('from',date('Y-m-01')); $to=$this->str('to',date('Y-m-d')); [$wins,$pipeline,$unassigned,$overdue]=$this->report($from,$to); ?>
<h1>Raport kierownika</h1><form class="filters" method="get" action="<?=$h(strtok(App()->createUrl('plugins/direct'),'?'))?>"><?php foreach(['r'=>'plugins/direct','plugin'=>'LimeControlCrm','function'=>'panel','team'=>$team,'tab'=>'reports'] as $k=>$v){echo CHtml::hiddenField($k,$v);} ?><label>Rozstrzygnięcia od <?=$input('from',$from,'date')?></label><label>Do <?=$input('to',$to,'date')?></label><?=$button('Pokaż')?></form><section class="sheet"><h2>Wynik sprzedaży w okresie</h2><p>Wygrane: <?=(int)$wins['won']?> · Przegrane: <?=(int)$wins['lost']?></p><h2>Otwarte szanse według etapu</h2><?php foreach(array_slice(LcCrmStore::STAGES,0,4) as $stage): ?><p><?=$h($l($stage))?> · <?=(int)($this->board('deal')[$stage]??0)?> · <?php foreach($pipeline[$stage]??[] as $cur=>$sum): ?><?=$h(number_format($sum/100,2,',',' ').' '.$cur)?> <?php endforeach; ?></p><?php endforeach; ?><h2>Obsługa</h2><p><a href="<?=$this->link(['tab'=>'list','type'=>'case','filter'=>'unassigned'])?>">Otwarte sprawy bez opiekuna: <?=(int)$unassigned?></a></p><p>Sprawy i zadania po terminie: <?=(int)$overdue?></p></section>
<?php elseif($this->tab==='csv'): ?><h1>Import i eksport kontaktów</h1><form method="post" enctype="multipart/form-data" class="sheet"><?=$post('preview')?><label>Plik CSV UTF-8<input type="file" name="csv" accept=".csv,text/csv" required></label><p>Nagłówek: <code>company_id,name,email,phone,tags</code>. Identyfikator firmy jest widoczny na jej karcie. Puste pole oznacza kontakt indywidualny.</p><?=$button('Pokaż podgląd')?> <a href="<?=$this->link(['tab'=>'csv','download'=>1])?>">Eksportuj kontakty zespołu</a></form>
<?php if($this->preview): ?><form method="post" class="sheet"><?=$post('import')?><?=CHtml::hiddenField('nonce',$this->preview['nonce'])?><h2>Podgląd importu</h2><p>Nowe wiersze utworzą kontakty. Dla istniejących zaznacz aktualizację danych. Puste kolumny zachowają zapisane wartości.</p><div class="overflow-x-auto"><table class="table"><thead><tr><th>Firma (ID)</th><th>Nazwa i e-mail</th><th>Działanie</th></tr></thead><tbody><?php foreach($this->preview['rows'] as $i=>$p): ?><tr><td><?=$h($p['values']['parent_id']?:'—')?></td><td><?=$h($p['values']['title'].' · '.$p['values']['email'])?></td><td><?php if($p['existing_id']): ?><label><span><input type="checkbox" name="merge[<?=$i?>]" value="1"> Aktualizuj kontakt #<?=$h($p['existing_id'])?></span></label><?php else: ?>Utwórz<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?=$button('Zastosuj import')?></form><?php endif; ?>
<?php elseif($this->tab==='settings' && $role==='admin'): ?><h1>Powiązania ankiet</h1><form class="sheet" method="post"><?=$post('mapping')?><p>Podaj numer ankiety z identyfikacją. Dla zapytań sprzedażowych wskaż zgodę typu Tak/Nie oraz pytania tekstowe z danymi. Dla spraw po zakupie wpisz klucz sklepu skonfigurowany we wtyczce Feedback. Zapis pustych ustawień przy numerze ankiety wyłącza oba przepływy.</p><div class="fields"><label>Przeznaczenie formularza<select class="select" name="form_target"><option value="deal">Szansa sprzedaży</option><option value="case">Sprawa obsługi</option></select></label><?php foreach(['survey'=>'Numer ankiety','store'=>'Klucz sklepu Feedback','consent'=>'Kod zgody (np. CONTACT)','person'=>'Kod osoby (PERSON)','email'=>'Kod e-mail (EMAIL)','company'=>'Opcjonalny kod firmy (COMPANY)','subject'=>'Opcjonalny kod tematu (SUBJECT)'] as $k=>$v): ?><label><?=$h($v)?> <?=$input($k,'',$k==='survey'?'number':'text')?></label><?php endforeach; ?></div><div class="actions"><?=$button('Zapisz mapowanie')?></div></form><h2>Mapowania zespołu</h2><ul><?php foreach($this->s->all('SELECT * FROM '.$this->s->table('lc_crm_survey').' WHERE team_id=? ORDER BY survey_id',[$team]) as $m): ?><li>#<?=$h($m['survey_id'])?> · <?=$m['form_target']==='case'?'Sprawa obsługi':'Szansa sprzedaży'?> · <?=$h(implode(' / ',array_filter([$m['store_key'],$m['optin_code'],$m['name_code'],$m['email_code'],$m['company_code'],$m['subject_code']])))?></li><?php endforeach; ?></ul>
<?php endif; endif; ?></main></body></html>
